import{d as t,S as a,i as s,l as r}from"./chunks/framework.CY2TYXqZ.js";const u=JSON.parse(`{"title":"Selected Excerpts","description":"A white-box assessment of Kestrel Press's editorial workspace, where contributors draft teaching materials and curriculum editors assemble selected excerpts into a course pack.","frontmatter":{"title":"Selected Excerpts","number":10,"layout":"challenge","difficulty":"medium","category":"web","backend":"flask","app":"app.py","packages":["flask"],"tools":["browser","network","repeater","code"],"source_visible":true,"source_files":["/workspace.py","/revisions.py","/course_pack.py","/templates/base.html","/templates/workbench.html","/templates/article.html","/templates/preview.html","/templates/course-pack.html","/templates/missing.html","/static/app.css"],"date":"2026-09-13T13:28:46.765Z","tags":["idor","access-control","ssti","template-injection","jinja2","flask"],"description":"A white-box assessment of Kestrel Press's editorial workspace, where contributors draft teaching materials and curriculum editors assemble selected excerpts into a course pack.","wasmModule":"/challenge/selected-excerpts/runtime.wasm","markdownBody":"\\n# Selected Excerpts\\n\\n**Client:** Kestrel Press, an independent educational publisher.\\n**Engagement:** White-box assessment of its contributor workspace and the course-pack preview assembled from selected excerpts.\\n\\n## Scope\\n\\nIn scope: the editorial workspace served at this origin, every HTTP endpoint it\\nexposes, and the source files mounted with the application.\\n\\nYou have access as an ordinary contributor, **Leah Navarro**. You may edit her\\ndrafts and inspect material that the curriculum team has already selected. You\\ndo not have editor approval rights and cannot change the course-pack list or\\nthe publisher's page templates.\\n\\nOut of scope: Kestrel Press's publishing system outside this exercise, other\\ncontributors' accounts, and denial of service.\\n\\n## Rules of engagement\\n\\nThis is an authorised exercise against a system Kestrel Press controls. Reach\\nthe objective, keep the evidence needed to explain it, and stop. Do not change\\nthe selection list or damage the teaching materials.\\n\\nKestrel Press has released the application's source code and page templates for\\nthis engagement. Read them alongside the running workspace.\\n\\n## Objective\\n\\nKestrel Press says that only editorially selected material can affect the\\ncourse-pack preview, and that contributor writing remains ordinary manuscript\\ntext throughout that process.\\n\\nTest that promise. Establish whether a contributor can influence a selected\\nexcerpt and whether that influence remains text when Kestrel Press assembles\\nthe course pack. The proof Kestrel Press will accept is the contents of\\n\`/flag.txt\`, which no normal page or source file serves.\\n\\n## Deliverable\\n\\nThe contents of \`/flag.txt\`, the requests that produced it, and an explanation\\nof the two separate failures required to reach it.\\n"},"headers":[],"relativePath":"challenge/selected-excerpts/index.md","filePath":"challenge/selected-excerpts/index.md"}`),n={name:"challenge/selected-excerpts/index.md"};function o(i,e,c,l,h,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="selected-excerpts" tabindex="-1">Selected Excerpts <a class="header-anchor" href="#selected-excerpts" aria-label="Permalink to “Selected Excerpts”">​</a></h1><p><strong>Client:</strong> Kestrel Press, an independent educational publisher. <strong>Engagement:</strong> White-box assessment of its contributor workspace and the course-pack preview assembled from selected excerpts.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope: the editorial workspace served at this origin, every HTTP endpoint it exposes, and the source files mounted with the application.</p><p>You have access as an ordinary contributor, <strong>Leah Navarro</strong>. You may edit her drafts and inspect material that the curriculum team has already selected. You do not have editor approval rights and cannot change the course-pack list or the publisher&#39;s page templates.</p><p>Out of scope: Kestrel Press&#39;s publishing system outside this exercise, other contributors&#39; accounts, and denial of service.</p><h2 id="rules-of-engagement" tabindex="-1">Rules of engagement <a class="header-anchor" href="#rules-of-engagement" aria-label="Permalink to “Rules of engagement”">​</a></h2><p>This is an authorised exercise against a system Kestrel Press controls. Reach the objective, keep the evidence needed to explain it, and stop. Do not change the selection list or damage the teaching materials.</p><p>Kestrel Press has released the application&#39;s source code and page templates for this engagement. Read them alongside the running workspace.</p><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to “Objective”">​</a></h2><p>Kestrel Press says that only editorially selected material can affect the course-pack preview, and that contributor writing remains ordinary manuscript text throughout that process.</p><p>Test that promise. Establish whether a contributor can influence a selected excerpt and whether that influence remains text when Kestrel Press assembles the course pack. The proof Kestrel Press will accept is the contents of <code>/flag.txt</code>, which no normal page or source file serves.</p><h2 id="deliverable" tabindex="-1">Deliverable <a class="header-anchor" href="#deliverable" aria-label="Permalink to “Deliverable”">​</a></h2><p>The contents of <code>/flag.txt</code>, the requests that produced it, and an explanation of the two separate failures required to reach it.</p>',14)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
